            {
              "display_text": "颜色有黑色和米色两种，按自己的搭配习惯挑就行。",
              "spoken_text": "颜色有黑色和米色两种，按自己的搭配习惯挑就行。",
              "kind": "product_claim",
              "fact_ids": [
                "SELLING"
              ]
            }
          ]
        },
        {
          "stage": "price",
          "sentences": [
            {
              "display_text": "价格方面，这款轻行可折叠通勤托特包原价九十九元。",
              "spoken_text": "价格方面，这款轻行可折叠通勤托特包原价九十九元。",
              "kind": "product_claim",
              "fact_ids": [
