        {
          "stage": "cta",
          "sentences": [
            {
              "display_text": "总结一下，这款轻行可折叠通勤托特包适合平时上班、购物、短途出行的人。",
              "spoken_text": "总结一下，这款轻行可折叠通勤托特包适合平时上班、购物、短途出行的人。",
              "kind": "product_claim",
              "fact_ids": [
                "NAME",
                "SELLING"
